<!DOCTYPE html>
<html lang="ru">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neon Snake Evolution</title>
    <style>
        :root {
            --bg-color: #0a0a12;
            --snake-color: #00ff9d;
            --food-color: #ff0055;
            --accent-color: #7000ff;
            --text-color: #ffffff;
        }

        body {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
            overflow: hidden;
            background: radial-gradient(circle at center, #1a1a2e 0%, #0a0a12 100%);
        }

        h1 {
            margin: 10px 0;
            font-size: 3rem;
            text-transform: uppercase;
            letter-spacing: 5px;
            text-shadow: 0 0 10px var(--snake-color), 0 0 20px var(--snake-color);
            margin-bottom: 5px;
        }

        #score {
            font-size: 24px;
            margin-bottom: 10px;
            font-weight: bold;
            color: var(--snake-color);
            text-shadow: 0 0 5px rgba(0, 255, 157, 0.5);
        }

        #game-container {
            position: relative;
            border: 4px solid rgba(255, 255, 255, 0.1);
            border-radius: 15px;
            padding: 10px;
            background: rgba(255, 255, 255, 0.03);
            box-shadow: 0 0 40px rgba(0, 0, 0, 0.8);
            backdrop-filter: blur(5px);
        }

        canvas {
            display: block;
            background-color: #05050a;
            border-radius: 8px;
            image-rendering: pixelated;
        }

        #game-over {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%) scale(0);
            text-align: center;
            display: none;
            background: rgba(10, 10, 20, 0.95);
            padding: 40px;
            border-radius: 20px;
            border: 2px solid var(--food-color);
            box-shadow: 0 0 30px var(--food-color);
            z-index: 10;
            transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275);
        }

        #game-over.show {
            display: block;
            transform: translate(-50%, -50%) scale(1);
        }

        #game-over h2 {
            font-size: 3rem;
            margin: 0;
            color: var(--food-color);
            text-shadow: 0 0 15px var(--food-color);
        }

        #game-over p {
            font-size: 1.2rem;
            margin: 20px 0;
        }

        .controls-hint {
            margin-top: 20px;
            font-size: 14px;
            color: #666;
            letter-spacing: 1px;
        }

        /* Анимация тряски при смерти */
        @keyframes shake {
            0% { transform: translate(-50%, -50%) translate(0, 0); }
            25% { transform: translate(-50%, -50%) translate(5px, 5px); }
            50% { transform: translate(-50%, -50%) translate(-5px, -5px); }
            75% { transform: translate(-50%, -50%) translate(5px, -5px); }
            100% { transform: translate(-50%, -50%) translate(0, 0); }
        }

        .shake {
            animation: shake 0.3s ease-in-out infinite;
        }
